// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.prank(nonOwner);
        bool success;
        try c.owned() { success = true; } catch { success = false; }
        assertTrue(!success, "owned should revert for non-owner");
    }
}
